    e.preventDefault(); // don't move the caret
    const kind = chip.getAttribute("data-anchor-kind");
    const id = chip.getAttribute("data-anchor-id")!;
    if (kind === "note") { buildAndPinFromRect(id, chip.getBoundingClientRect()); }
    else if (kind === "comment") { void openUserCommentPopover(id, chip); }
    else if (kind === "suggestion") { openSuggestionPopover(id, chip); }
    return;
